"""Deterministic validation of simulation proposals (FR-003, INV-003, SEC-001).

The validator is the authoritative gate. Candidate-provided status, safety text,
balance, holdings or rule version are never trusted. The caller supplies a
``SafetyContext`` built from independent sources: the trusted account snapshot,
the trusted rule catalog and the instrument quote currency. The verdict is a
pure function of those inputs, so the same proposal/snapshot/rule version
replays identically (NFR-003).

Out of scope this session (do not invent): reference-price deviation limits,
fees and extra position caps. They are pending policy inputs.

No broker, network or credential access is performed here.
"""
from __future__ import annotations

from collections.abc import Mapping
from decimal import (
    MAX_EMAX,
    MIN_EMIN,
    ROUND_HALF_EVEN,
    Clamped,
    Context,
    Decimal,
    DecimalException,
    Inexact,
    InvalidOperation,
    Overflow,
    Rounded,
    Subnormal,
    Underflow,
    getcontext,
    localcontext,
)
from typing import Any

from .models import (
    Action,
    HoldingsSnapshot,
    ProposalStatus,
    ReasonCode,
    RuleSet,
    SafetyContext,
    SafetyVerdict,
    SimulationProposal,
    parse_decimal,
    parse_holdings_snapshot,
)

# NFR-003: an explicit, caller-independent precision budget for exact amounts.
MAX_EXACT_DECIMAL_PRECISION = 64
_EXACTNESS_SIGNALS = (
    Clamped,
    Inexact,
    InvalidOperation,
    Overflow,
    Rounded,
    Subnormal,
    Underflow,
)

REAL_EXECUTION_ACTIONS = frozenset(
    {
        "execute",
        "executed",
        "place_order",
        "submit_order",
        "real_order",
        "live_order",
        "broker_order",
    }
)
REAL_EXECUTION_MODES = frozenset({"live", "real", "broker", "production", "execute"})
REAL_EXECUTION_FLAGS = (
    "real_execution",
    "live",
    "live_trading",
    "submit_order",
    "place_order",
    "execute_now",
    "broker",
    "broker_order",
    "broker_order_id",
)
SELF_AUTHORIZATION_KEYS = (
    "status",
    "safe",
    "is_safe",
    "approved",
    "authorized",
    "authorization",
    "verdict",
    "safety_verdict",
)


def _string_or_none(value: Any) -> str | None:
    if isinstance(value, str) and value.strip():
        return value.strip()
    return None


def _trusted_rule_version(context: SafetyContext | None) -> str | None:
    if isinstance(context, SafetyContext) and isinstance(context.rule_set, RuleSet):
        return context.rule_set.version
    return None


def _exact_product(left: Decimal, right: Decimal) -> Decimal | None:
    """Multiply exactly without depending on the caller's Decimal context.

    The caller may run under any precision, range, rounding, clamp or trap
    settings. This helper builds an explicit ``Context`` (no inherited state)
    and returns ``None`` when an operand is out of range or the exact product
    does not fit. Callers must then fail closed rather than accept a rounded or
    subnormal amount that could understate the cost.
    """
    exact_context = Context(
        prec=MAX_EXACT_DECIMAL_PRECISION,
        rounding=ROUND_HALF_EVEN,
        Emin=MIN_EMIN,
        Emax=MAX_EMAX,
        capitals=1,
        clamp=0,
        traps=[],
    )
    with localcontext(exact_context):
        active = getcontext()
        if not active.is_normal(left) or not active.is_normal(right):
            return None
        try:
            product = left * right
        except DecimalException:
            return None
        unsafe = any(active.flags[signal] for signal in _EXACTNESS_SIGNALS)
        finite = product.is_finite()
    if unsafe or not finite:
        return None
    return product


def _trusted_snapshot_id(context: SafetyContext | None) -> str | None:
    if not isinstance(context, SafetyContext):
        return None
    snapshot = context.holdings_snapshot
    if isinstance(snapshot, HoldingsSnapshot):
        return snapshot.snapshot_id
    if isinstance(snapshot, Mapping):
        raw = snapshot.get("snapshot_id")
        if isinstance(raw, str) and raw.strip():
            return raw.strip()
    return None


def _reject(
    reason: ReasonCode,
    message: str,
    candidate: SimulationProposal | None = None,
    context: SafetyContext | None = None,
    ignored: tuple[str, ...] = (),
) -> SafetyVerdict:
    return SafetyVerdict(
        accepted=False,
        reason_code=reason,
        message=message,
        status=ProposalStatus.REJECTED,
        action=_string_or_none(getattr(candidate, "action", None)),
        rule_version=_trusted_rule_version(context),
        snapshot_id=_trusted_snapshot_id(context),
        instrument=context.instrument if isinstance(context, SafetyContext) else None,
        is_noop=False,
        ignored_claims=ignored,
    )


def _accept(
    candidate: SimulationProposal,
    context: SafetyContext,
    action: Action,
    ignored: tuple[str, ...],
) -> SafetyVerdict:
    return SafetyVerdict(
        accepted=True,
        reason_code=ReasonCode.ACCEPTED,
        message="proposal accepted by deterministic safety rules",
        status=ProposalStatus.ACCEPTED,
        action=action.value,
        rule_version=_trusted_rule_version(context),
        snapshot_id=_trusted_snapshot_id(context),
        instrument=context.instrument,
        is_noop=action is Action.HOLD,
        ignored_claims=ignored,
    )


def _ignored_claims(candidate: SimulationProposal) -> tuple[str, ...]:
    claims: set[str] = set()
    if candidate.status is not None:
        claims.add("status")
    for key in SELF_AUTHORIZATION_KEYS:
        if key != "status" and key in candidate.extra:
            claims.add(key)
    return tuple(sorted(claims))


def _is_real_execution(candidate: SimulationProposal) -> bool:
    action = _string_or_none(candidate.action)
    if action is not None and action.lower() in REAL_EXECUTION_ACTIONS:
        return True

    status = _string_or_none(candidate.status)
    if status is not None and status.lower() in REAL_EXECUTION_ACTIONS:
        return True

    extra = candidate.extra
    mode = extra.get("execution_mode")
    if isinstance(mode, str) and mode.strip().lower() in REAL_EXECUTION_MODES:
        return True

    for key in REAL_EXECUTION_FLAGS:
        if key in extra and extra[key] not in (None, False, "", 0):
            return True
    return False


def _resolve_trusted_snapshot(
    context: SafetyContext,
) -> tuple[HoldingsSnapshot | None, ReasonCode | None]:
    trusted = context.holdings_snapshot
    if trusted is None:
        return None, ReasonCode.UNRESOLVED_HOLDINGS_SNAPSHOT
    if isinstance(trusted, HoldingsSnapshot):
        return trusted, None
    parsed, error = parse_holdings_snapshot(trusted)
    if parsed is None:
        return None, ReasonCode.UNRESOLVED_HOLDINGS_SNAPSHOT
    return parsed, error


def _check_candidate_snapshot(
    candidate: SimulationProposal,
    trusted: HoldingsSnapshot,
) -> ReasonCode | None:
    reference = candidate.holdings_snapshot
    if reference is None:
        return ReasonCode.MISSING_HOLDINGS_SNAPSHOT
    if isinstance(reference, str):
        if reference.strip() != trusted.snapshot_id:
            return ReasonCode.HOLDINGS_SNAPSHOT_MISMATCH
        return None
    if not isinstance(reference, Mapping) and not isinstance(reference, HoldingsSnapshot):
        return ReasonCode.INVALID_HOLDINGS_SNAPSHOT_REFERENCE
    parsed, error = parse_holdings_snapshot(reference)
    if parsed is None:
        return error or ReasonCode.INVALID_HOLDINGS_SNAPSHOT
    if not parsed.is_same_as(trusted):
        return ReasonCode.HOLDINGS_SNAPSHOT_MISMATCH
    return None


def _validate(candidate: SimulationProposal, context: SafetyContext) -> SafetyVerdict:
    ignored = _ignored_claims(candidate)

    # SEC-001: real execution is permanently rejected, before any other field.
    if _is_real_execution(candidate):
        return _reject(
            ReasonCode.REAL_EXECUTION_REQUESTED,
            "real broker execution is permanently rejected",
            candidate,
            context,
            ignored,
        )

    if candidate.action is None or (
        isinstance(candidate.action, str) and not candidate.action.strip()
    ):
        return _reject(ReasonCode.MISSING_ACTION, "missing action", candidate, context, ignored)
    action = Action.parse(candidate.action)
    if action is None:
        return _reject(
            ReasonCode.UNSUPPORTED_ACTION,
            "unsupported action; only buy/sell/hold are simulated",
            candidate,
            context,
            ignored,
        )

    if candidate.units is None:
        return _reject(ReasonCode.MISSING_UNITS, "missing units", candidate, context, ignored)
    units, _ = parse_decimal(candidate.units)
    if units is None:
        return _reject(
            ReasonCode.INVALID_UNITS,
            "units must be a finite number",
            candidate,
            context,
            ignored,
        )
    if units < 0:
        return _reject(
            ReasonCode.NEGATIVE_UNITS,
            "negative units are outside the explicit long-only policy",
            candidate,
            context,
            ignored,
        )
    if action is Action.HOLD:
        if units != 0:
            return _reject(
                ReasonCode.HOLD_UNITS_NOT_ZERO,
                "hold requires units == 0",
                candidate,
                context,
                ignored,
            )
    elif units == 0:
        return _reject(
            ReasonCode.NON_POSITIVE_UNITS,
            "buy/sell requires units > 0",
            candidate,
            context,
            ignored,
        )

    if candidate.price is None:
        return _reject(ReasonCode.MISSING_PRICE, "missing price", candidate, context, ignored)
    price, price_error = parse_decimal(candidate.price)
    if price is None:
        if price_error == "non_finite":
            return _reject(
                ReasonCode.NON_FINITE_PRICE,
                "price must be finite",
                candidate,
                context,
                ignored,
            )
        return _reject(
            ReasonCode.INVALID_PRICE,
            "price must be numeric",
            candidate,
            context,
            ignored,
        )
    if price <= 0:
        return _reject(
            ReasonCode.NON_POSITIVE_PRICE,
            "price must be greater than zero",
            candidate,
            context,
            ignored,
        )

    if candidate.currency is None or (
        isinstance(candidate.currency, str) and not candidate.currency.strip()
    ):
        return _reject(ReasonCode.MISSING_CURRENCY, "missing currency", candidate, context, ignored)
    if not isinstance(candidate.currency, str):
        return _reject(
            ReasonCode.INVALID_CURRENCY,
            "currency must be a string",
            candidate,
            context,
            ignored,
        )
    if candidate.currency.strip().upper() != context.instrument_currency.strip().upper():
        return _reject(
            ReasonCode.CURRENCY_MISMATCH,
            "candidate currency does not match the instrument quote currency",
            candidate,
            context,
            ignored,
        )

    trusted, snapshot_error = _resolve_trusted_snapshot(context)
    if trusted is None:
        return _reject(
            snapshot_error or ReasonCode.UNRESOLVED_HOLDINGS_SNAPSHOT,
            "trusted holdings snapshot is unavailable or invalid",
            candidate,
            context,
            ignored,
        )

    candidate_snapshot_error = _check_candidate_snapshot(candidate, trusted)
    if candidate_snapshot_error is not None:
        return _reject(
            candidate_snapshot_error,
            "candidate holdings snapshot is missing, malformed or not the trusted snapshot",
            candidate,
            context,
            ignored,
        )

    if trusted.currency.strip().upper() != context.instrument_currency.strip().upper():
        return _reject(
            ReasonCode.CURRENCY_MISMATCH,
            "trusted snapshot currency does not match the instrument quote currency",
            candidate,
            context,
            ignored,
        )
    if trusted.cash < 0:
        return _reject(
            ReasonCode.INVALID_CASH,
            "trusted cash must not be negative",
            candidate,
            context,
            ignored,
        )
    if any(quantity < 0 for quantity in trusted.positions.values()):
        return _reject(
            ReasonCode.NEGATIVE_HOLDINGS,
            "negative holdings are outside the explicit long-only policy",
            candidate,
            context,
            ignored,
        )
    if not trusted.positions and not trusted.flat_declared:
        return _reject(
            ReasonCode.UNDECLARED_FLAT,
            "empty holdings require an explicit flat declaration",
            candidate,
            context,
            ignored,
        )

    if candidate.rule_version is None or (
        isinstance(candidate.rule_version, str) and not candidate.rule_version.strip()
    ):
        return _reject(
            ReasonCode.MISSING_RULE_VERSION,
            "missing rule version",
            candidate,
            context,
            ignored,
        )
    if not isinstance(candidate.rule_version, str):
        return _reject(
            ReasonCode.UNKNOWN_RULE_VERSION,
            "rule version must be a string",
            candidate,
            context,
            ignored,
        )
    claimed_rule = candidate.rule_version.strip()
    trusted_rules = context.rule_set
    if trusted_rules is None:
        return _reject(
            ReasonCode.UNKNOWN_RULE_VERSION,
            "trusted rule set is unavailable",
            candidate,
            context,
            ignored,
        )
    if not isinstance(trusted_rules, RuleSet):
        return _reject(
            ReasonCode.INVALID_RULE_SET,
            "trusted rule set has an invalid type",
            candidate,
            context,
            ignored,
        )
    if not trusted_rules.long_only:
        return _reject(
            ReasonCode.UNSUPPORTED_RULE_POLICY,
            "only the explicit long-only policy is implemented",
            candidate,
            context,
            ignored,
        )
    available = context.available_rule_versions or frozenset({trusted_rules.version})
    if claimed_rule not in available:
        return _reject(
            ReasonCode.UNKNOWN_RULE_VERSION,
            "candidate rule version is not in the trusted rule catalog",
            candidate,
            context,
            ignored,
        )
    if claimed_rule != trusted_rules.version:
        return _reject(
            ReasonCode.RULE_VERSION_MISMATCH,
            "candidate rule version does not match the pinned trusted rule version",
            candidate,
            context,
            ignored,
        )

    if action is Action.BUY:
        cost = _exact_product(units, price)
        if cost is None:
            return _reject(
                ReasonCode.AMOUNT_PRECISION_UNSUPPORTED,
                "buy cost cannot be computed exactly within the safety precision budget",
                candidate,
                context,
                ignored,
            )
        if cost > trusted.cash:
            return _reject(
                ReasonCode.INSUFFICIENT_CASH,
                "buy cost exceeds trusted cash",
                candidate,
                context,
                ignored,
            )
    elif action is Action.SELL:
        held = trusted.positions.get(context.instrument, Decimal("0"))
        if held < units:
            return _reject(
                ReasonCode.INSUFFICIENT_HOLDINGS,
                "sell units exceed trusted holdings",
                candidate,
                context,
                ignored,
            )

    return _accept(candidate, context, action, ignored)


def validate_proposal(proposal: Any, *, context: SafetyContext) -> SafetyVerdict:
    """Return a deterministic accept/reject verdict for a simulation proposal.

    ``proposal`` may be a ``SimulationProposal`` or a mapping with the fixed
    contract fields. ``context`` must contain the independently trusted snapshot
    and rule set. Any unexpected error fails closed with ``VALIDATION_ERROR``.
    """
    candidate: SimulationProposal | None = None
    try:
        if not isinstance(context, SafetyContext):
            return _reject(
                ReasonCode.VALIDATION_ERROR,
                "a trusted SafetyContext is required",
            )
        if isinstance(proposal, SimulationProposal):
            candidate = proposal
        elif isinstance(proposal, Mapping):
            candidate = SimulationProposal.from_mapping(proposal)
        else:
            return _reject(
                ReasonCode.INVALID_PROPOSAL,
                "proposal must be a mapping or SimulationProposal",
                None,
                context,
            )
        return _validate(candidate, context)
    except Exception:
        return _reject(
            ReasonCode.VALIDATION_ERROR,
            "unexpected validation failure; failing closed",
            candidate,
            context if isinstance(context, SafetyContext) else None,
        )

"""Global data sufficiency admission decision (proceed / abstain / review).

Anchors: FR-004, INV-004, NFR-004, ADR-001. Deterministic and fail-closed.

Decision priority (first match wins):

1. invalid analysis cutoff                          -> review
2. any label violation (incl. neutral relabel)      -> review
3. empty / missing required / duplicate conflict    -> review
4. any future evidence (as_of > cutoff)             -> review
5. any required domain ``unknown``                  -> review
6. any required domain ``unavailable``              -> abstain
7. all five required domains valid and available    -> proceed

INV-004: unknown maps to review (default-deny), never abstain and never
neutral; unavailable maps to abstain. Unknown domains are listed in
``insufficient_domains``. Any exception at the boundary becomes ``review``; the
result is never silently degraded.
"""

from __future__ import annotations

from collections import defaultdict
from collections.abc import Iterable
from typing import Any

from .classifier import classify
from .contracts import (
    REQUIRED_DOMAINS,
    AdmissionDecision,
    ContractError,
    DomainLabel,
    LabelViolation,
    RawObservation,
    parse_iso_date,
    validate_label,
)


def _label_or_violation(raw: Any) -> tuple[DomainLabel | None, LabelViolation | None]:
    """Coerce a raw observation into a label, or report why it could not be."""
    if isinstance(raw, DomainLabel):
        return raw, None
    if isinstance(raw, RawObservation):
        return classify(raw), None
    if isinstance(raw, dict):
        try:
            observation = RawObservation(**raw)
        except TypeError as exc:
            return (
                None,
                LabelViolation(
                    raw.get("domain") if isinstance(raw, dict) else None,
                    "invalid_observation",
                    f"observation is not constructible: {exc}",
                ),
            )
        return classify(observation), None
    return (
        None,
        LabelViolation(None, "invalid_observation", f"unsupported observation type {type(raw).__name__}"),
    )


def admit(
    observations: Iterable[Any] | None,
    analysis_cutoff: str,
) -> AdmissionDecision:
    """Decide global data sufficiency from domain observations (FR-004)."""
    try:
        return _admit(observations, analysis_cutoff)
    except Exception as exc:  # noqa: BLE001 - fail-closed boundary, never propagate.
        return AdmissionDecision(
            decision="review",
            insufficient_domains=list(REQUIRED_DOMAINS),
            labels=[],
            reason=f"exception:{type(exc).__name__}",
            violations=[
                LabelViolation(None, "exception", f"{type(exc).__name__}: {exc}")
            ],
            analysis_cutoff=analysis_cutoff if isinstance(analysis_cutoff, str) else None,
        )


def _admit(observations: Iterable[Any] | None, analysis_cutoff: str) -> AdmissionDecision:
    violations: list[LabelViolation] = []

    # 1. Analysis cutoff must be a valid ISO date.
    try:
        cutoff = parse_iso_date(analysis_cutoff)
    except ContractError as exc:
        return AdmissionDecision(
            decision="review",
            insufficient_domains=list(REQUIRED_DOMAINS),
            labels=[],
            reason=f"invalid_cutoff: {exc}",
            violations=[LabelViolation(None, "invalid_cutoff", str(exc))],
            analysis_cutoff=analysis_cutoff if isinstance(analysis_cutoff, str) else None,
        )

    if observations is None:
        observations = []

    labels: list[DomainLabel] = []
    for raw in observations:
        label, violation = _label_or_violation(raw)
        if violation is not None:
            violations.append(violation)
            continue
        assert label is not None
        labels.append(label)

    # 2. Label violations (unknown domain/status, neutral relabel, bad date/reason).
    for label in labels:
        violations.extend(validate_label(label))

    # 3. Required-domain coverage and duplicate conflicts.
    grouped: dict[str, list[DomainLabel]] = defaultdict(list)
    for label in labels:
        grouped[label.domain].append(label)

    missing_domains = [domain for domain in REQUIRED_DOMAINS if domain not in grouped]
    for domain in missing_domains:
        violations.append(
            LabelViolation(domain, "missing_domain", f"required domain {domain!r} absent")
        )

    for domain in REQUIRED_DOMAINS:
        group = grouped.get(domain, [])
        if len(group) > 1:
            statuses = {label.status for label in group}
            as_ofs = {label.as_of for label in group}
            if len(statuses) > 1 or len(as_ofs) > 1:
                violations.append(
                    LabelViolation(
                        domain,
                        "duplicate_conflict",
                        f"conflicting labels for domain {domain!r}",
                    )
                )

    # 3b. Empty input is explicitly insufficient.
    if not labels:
        violations.append(
            LabelViolation(None, "empty_input", "no domain observations supplied")
        )

    # Deterministic label ordering for the returned decision.
    ordered_labels = _order_labels(labels)

    if violations:
        return AdmissionDecision(
            decision="review",
            insufficient_domains=_ordered_unique(
                [v.domain for v in violations if v.domain] + missing_domains
            ),
            labels=ordered_labels,
            reason="label/contract violations; default-deny review",
            violations=violations,
            analysis_cutoff=analysis_cutoff,
        )

    # 4. Future evidence (as_of later than the cutoff).
    future = [label for label in labels if parse_iso_date(label.as_of) > cutoff]
    if future:
        return AdmissionDecision(
            decision="review",
            insufficient_domains=_ordered_unique([label.domain for label in future]),
            labels=ordered_labels,
            reason="evidence dated after the analysis cutoff",
            violations=[
                LabelViolation(
                    label.domain,
                    "future_date",
                    f"as_of {label.as_of} is after cutoff {analysis_cutoff}",
                )
                for label in future
            ],
            analysis_cutoff=analysis_cutoff,
        )

    # 5. Unknown -> review (default-deny), never abstain/neutral.
    unknown = [label for label in labels if label.status == "unknown"]
    if unknown:
        return AdmissionDecision(
            decision="review",
            insufficient_domains=_ordered_unique([label.domain for label in unknown]),
            labels=ordered_labels,
            reason="unknown domain data; default-deny (INV-004)",
            violations=[
                LabelViolation(label.domain, "unknown_domain", label.reason)
                for label in unknown
            ],
            analysis_cutoff=analysis_cutoff,
        )

    # 6. Unavailable -> abstain.
    unavailable = [label for label in labels if label.status == "unavailable"]
    if unavailable:
        return AdmissionDecision(
            decision="abstain",
            insufficient_domains=_ordered_unique([label.domain for label in unavailable]),
            labels=ordered_labels,
            reason="unavailable domain data; abstain",
            analysis_cutoff=analysis_cutoff,
        )

    # 7. All required domains available (and, by construction, only those five).
    return AdmissionDecision(
        decision="proceed",
        insufficient_domains=[],
        labels=ordered_labels,
        reason="all required domains available",
        analysis_cutoff=analysis_cutoff,
    )


def _order_labels(labels: Iterable[DomainLabel]) -> list[DomainLabel]:
    order = {domain: index for index, domain in enumerate(REQUIRED_DOMAINS)}
    return sorted(
        labels,
        key=lambda label: (order.get(label.domain, len(order)), label.domain, label.status, label.as_of),
    )


def _ordered_unique(values: Iterable[str]) -> list[str]:
    seen: set[str] = set()
    result: list[str] = []
    for value in values:
        if value not in seen:
            seen.add(value)
            result.append(value)
    return result


__all__ = ["admit"]

"""Offline, versioned gate replay against the audit chain.

Anchors: FR-005, NFR-003 (determinism), INV-005. Design: ADR-003 §2.8.

Replay never imports C/D/B leaf modules. The caller supplies a versioned gate
registry ``{gate_id: {rules_version: callable(inputs) -> observed}}``; replay
re-executes the callback on a deep copy of the recorded inputs and compares
canonical JSON with the recorded ``observed``.
"""
from __future__ import annotations

import copy
from collections.abc import Callable
from typing import Any

from .records import AuditError, AuditRecord, canonical_json, payload_ref
from .store import AuditStore, VerificationResult

GateCallback = Callable[[Any], Any]
GateRegistry = dict[str, dict[str, GateCallback]]

#: ``pass`` = re-executed gate matched; ``review`` = any failure; ``inconclusive``
#: = no gate records to replay (never reported as a 100% pass).
STATUS_PASS = "pass"
STATUS_REVIEW = "review"
STATUS_INCONCLUSIVE = "inconclusive"


class ReplayResult:
    """Outcome of replaying one record (FR-005, NFR-003, INV-005 / ADR-003).

    ``reason`` names the cause (``ok``, ``gate_missing``, ``version_unknown``,
    ``missing_key``, ``rules_version_mismatch``, ``input_tampered``,
    ``non_json_result``, ``callback_error``, ``observed_mismatch``,
    ``malformed_payload``). ``count`` is 1 for a gate replay, 0 for an excluded
    non-gate record.
    """

    __slots__ = ("record_id", "gate_id", "rules_version", "status", "reason", "detail", "count")

    def __init__(
        self, *, record_id: str, gate_id: str | None, rules_version: str | None,
        status: str, reason: str, detail: str = "", count: int,
    ) -> None:
        self.record_id = record_id
        self.gate_id = gate_id
        self.rules_version = rules_version
        self.status = status
        self.reason = reason
        self.detail = detail
        self.count = count

    def to_dict(self) -> dict:
        """Return a plain dict for this single-record replay result (INV-005 / ADR-003)."""
        return {
            "record_id": self.record_id, "gate_id": self.gate_id,
            "rules_version": self.rules_version, "status": self.status,
            "reason": self.reason, "detail": self.detail, "count": self.count,
        }

    def __repr__(self) -> str:  # pragma: no cover - debug aid
        return f"ReplayResult(record_id={self.record_id!r}, status={self.status!r}, reason={self.reason!r})"


class ReplayRunResult:
    """Aggregate outcome of :func:`replay_run` (FR-005, NFR-003, INV-005 / ADR-003).

    ``gate_total`` counts only gate records; ``inconclusive`` is True when
    ``gate_total == 0``. ``status`` is ``pass`` only when there was at least one
    gate and all passed; otherwise ``review`` (or ``inconclusive``). It never
    reports a pass with an empty denominator.
    """

    __slots__ = ("run_id", "status", "results", "gate_total", "passed", "reviewed", "inconclusive", "detail")

    def __init__(self, *, run_id: str, results: list[ReplayResult], detail: str = "") -> None:
        self.run_id = run_id
        self.results = results
        self.gate_total = sum(r.count for r in results)
        self.passed = sum(1 for r in results if r.status == STATUS_PASS)
        self.reviewed = sum(1 for r in results if r.status == STATUS_REVIEW)
        self.inconclusive = self.gate_total == 0
        if self.inconclusive:
            self.status = STATUS_INCONCLUSIVE
        elif self.reviewed > 0:
            self.status = STATUS_REVIEW
        else:
            self.status = STATUS_PASS
        self.detail = detail

    def _force_review(self) -> ReplayRunResult:
        """Overwrite the aggregate status to review for a pre-replay failure."""
        self.status = STATUS_REVIEW
        self.inconclusive = False
        return self

    def to_dict(self) -> dict:
        """Return a plain dict for this run-level replay result (INV-005 / ADR-003)."""
        return {
            "run_id": self.run_id, "status": self.status, "gate_total": self.gate_total,
            "passed": self.passed, "reviewed": self.reviewed, "inconclusive": self.inconclusive,
            "detail": self.detail, "results": [r.to_dict() for r in self.results],
        }

    def __repr__(self) -> str:  # pragma: no cover - debug aid
        return (
            f"ReplayRunResult(run_id={self.run_id!r}, status={self.status!r}, "
            f"gate_total={self.gate_total}, passed={self.passed})"
        )


def _review(record_id: str, reason: str, *, gate_id: str | None = None, rules_version: str | None = None,
            detail: str = "", count: int = 1) -> ReplayResult:
    return ReplayResult(
        record_id=record_id, gate_id=gate_id, rules_version=rules_version,
        status=STATUS_REVIEW, reason=reason, detail=detail, count=count,
    )


def replay_record(record: AuditRecord, registry: GateRegistry) -> ReplayResult:
    """Replay a single record against ``registry`` (FR-005, NFR-003, INV-005 / ADR-003).

    Verifies this record's own ``record_hash`` and ``payload_ref``, not whole-chain
    integrity (use :func:`replay_run`). The callback receives a deep copy of
    ``inputs``; any mutation, exception, non-JSON result or mismatch yields
    ``review``. A malformed registry (non-dict) or payload yields ``review``
    instead of raising. A record carrying any replay field (gate_id/inputs/
    observed) is treated as gate intent and reviewed if incomplete; a pure
    narrative record is ``inconclusive`` with ``count == 0``.
    """
    try:
        # Check the payload content digest first: a tampered payload_ref must
        # surface as payload_ref_mismatch even though it also breaks the overall
        # record_hash. Invalid JSON still yields a review without escaping.
        payload = record.payload
        if record.payload_ref != payload_ref(payload):
            return _review(record.record_id, "payload_ref_mismatch",
                           detail="stored payload_ref does not match the payload")
        if record.recompute_hash() != record.record_hash:
            return _review(record.record_id, "record_hash_mismatch")
    except (AuditError, ValueError, TypeError) as exc:
        return _review(record.record_id, "malformed_payload", detail=str(exc))

    # Treat a record as gate intent if it carries ANY replay-specific field. A
    # malformed gate missing only ``gate_id`` must be reviewed, not silently
    # excluded from the agreement denominator. Pure narrative records
    # (action/outcome/note only) stay inconclusive; a payload with none of the
    # three replay fields cannot be auto-inferred as a gate (see README).
    if not isinstance(payload, dict):
        return ReplayResult(
            record_id=record.record_id, gate_id=None, rules_version=None,
            status=STATUS_INCONCLUSIVE, reason="not_a_gate_record", count=0,
        )
    replay_fields = {"gate_id", "inputs", "observed"}
    present = replay_fields & payload.keys()
    if not present:
        return ReplayResult(
            record_id=record.record_id, gate_id=None, rules_version=None,
            status=STATUS_INCONCLUSIVE, reason="not_a_gate_record", count=0,
        )

    gate_id = payload.get("gate_id")
    if not isinstance(gate_id, str) or not gate_id:
        return _review(record.record_id, "missing_key", rules_version=record.rules_version,
                       detail="gate record is missing a non-empty gate_id")

    for key in ("inputs", "observed"):
        if key not in payload:
            return _review(record.record_id, "missing_key", gate_id=gate_id,
                           rules_version=record.rules_version, detail=f"payload missing {key!r}")

    payload_version = payload.get("rules_version")
    if payload_version is not None and payload_version != record.rules_version:
        return _review(record.record_id, "rules_version_mismatch", gate_id=gate_id,
                       rules_version=record.rules_version,
                       detail=f"payload.rules_version {payload_version!r} != record {record.rules_version!r}")

    if not isinstance(registry, dict):
        return _review(record.record_id, "gate_missing", gate_id=gate_id,
                       rules_version=record.rules_version, detail="registry is not a mapping")
    versions = registry.get(gate_id)
    if not isinstance(versions, dict):
        return _review(record.record_id, "gate_missing", gate_id=gate_id,
                       rules_version=record.rules_version, detail=f"gate {gate_id!r} is not registered")
    callback = versions.get(record.rules_version)
    if not callable(callback):
        return _review(record.record_id, "version_unknown", gate_id=gate_id,
                       rules_version=record.rules_version,
                       detail=f"gate {gate_id!r} has no version {record.rules_version!r}")

    recorded_inputs = payload["inputs"]
    recorded_observed = payload["observed"]
    inputs_copy = copy.deepcopy(recorded_inputs)
    try:
        produced = callback(inputs_copy)
    except Exception as exc:  # callback failure -> review, never pass
        return _review(record.record_id, "callback_error", gate_id=gate_id,
                       rules_version=record.rules_version, detail=f"{type(exc).__name__}: {exc}")

    try:
        if canonical_json(inputs_copy) != canonical_json(recorded_inputs):
            return _review(record.record_id, "input_tampered", gate_id=gate_id,
                           rules_version=record.rules_version, detail="callback mutated its input copy")
        produced_bytes = canonical_json(produced)
        expected_bytes = canonical_json(recorded_observed)
    except AuditError as exc:
        return _review(record.record_id, "non_json_result", gate_id=gate_id,
                       rules_version=record.rules_version, detail=str(exc))

    if produced_bytes != expected_bytes:
        return _review(record.record_id, "observed_mismatch", gate_id=gate_id,
                       rules_version=record.rules_version,
                       detail="re-executed gate result differs from recorded observed")

    return ReplayResult(
        record_id=record.record_id, gate_id=gate_id, rules_version=record.rules_version,
        status=STATUS_PASS, reason="ok", count=1,
    )


def verify_against_trusted_head(store: AuditStore, trusted_head: Any) -> VerificationResult:
    """Compare the current head with an externally stored head (FR-005, INV-005).

    Malformed input (non-dict, missing keys, empty dict, non-int count) returns
    ``head_mismatch`` (review) rather than raising. The whole chain is verified
    first, so an equal head over a corrupted middle still fails. Inequality is not
    proof of tampering: legitimate appends also change the head, so it yields
    ``head_mismatch`` for human confirmation only.
    """
    if not isinstance(trusted_head, dict):
        return VerificationResult(False, "head_mismatch", "trusted head must be a mapping")

    required = ("record_id", "record_hash", "count")
    if any(key not in trusted_head for key in required):
        return VerificationResult(False, "head_mismatch", "trusted head missing required fields")
    count = trusted_head["count"]
    if not isinstance(count, int) or isinstance(count, bool):
        return VerificationResult(False, "head_mismatch", "trusted head count must be an int")

    chain = store.verify_chain()
    if not chain.ok:
        return VerificationResult(False, "chain_broken", f"chain not consistent: {chain.reason} ({chain.detail})")

    current = store.head()
    expected = {
        "record_id": trusted_head["record_id"],
        "record_hash": trusted_head["record_hash"],
        "count": count,
    }
    if current != expected:
        return VerificationResult(False, "head_mismatch", f"current head {current} != trusted head {expected}")
    return VerificationResult(True, "ok", "head matches trusted snapshot")


def replay_run(
    store: AuditStore,
    run_id: str,
    registry: GateRegistry,
    trusted_head: dict | None = None,
) -> ReplayRunResult:
    """Replay all gate records of ``run_id`` from one verified snapshot (FR-005, NFR-003, INV-005 / ADR-003).

    Order: verify the whole chain, then (if given) compare the trusted head, then
    replay each gate record from the *same* verified snapshot. A broken chain or
    head mismatch aborts to an overall review without replaying. Non-gate records
    are excluded from the agreement denominator; zero gate records yields
    ``inconclusive``, not a 100% pass. Replay never mutates stored records.
    """
    try:
        records = store.verified_records(run_id)
    except AuditError as exc:
        return ReplayRunResult(
            run_id=run_id, results=[], detail=f"chain not consistent: {exc.message}",
        )._force_review()

    if trusted_head is not None:
        head_result = verify_against_trusted_head(store, trusted_head)
        if not head_result.ok:
            return ReplayRunResult(
                run_id=run_id, results=[],
                detail=f"trusted head check failed: {head_result.reason}",
            )._force_review()

    results = [replay_record(record, registry) for record in records]
    return ReplayRunResult(run_id=run_id, results=results)

"""SQLite-backed append-only audit store with a single global hash chain.

Anchors: FR-005, INV-005, NFR-004. Design: ADR-003 §2.1-§2.7.

One global chain ordered by the SQLite autoincrement ``sequence``. Writes run in
``BEGIN IMMEDIATE`` so concurrent connections serialise "read head then append".
``BEFORE UPDATE``/``BEFORE DELETE`` triggers reject mutation, so ``append`` is
the only write path.
"""
from __future__ import annotations

import json
import sqlite3
from typing import Any

from .records import (
    AuditError,
    AuditRecord,
    canonical_json,
    compute_record_hash,
    make_record,
    payload_ref,
    validate_append_inputs,
)

_SCHEMA = """
CREATE TABLE IF NOT EXISTS audit_records (
    sequence            INTEGER PRIMARY KEY AUTOINCREMENT,
    record_id           TEXT NOT NULL UNIQUE,
    run_id              TEXT NOT NULL,
    timestamp           TEXT NOT NULL,
    entry_type          TEXT NOT NULL,
    payload_ref         TEXT NOT NULL,
    rules_version       TEXT NOT NULL,
    previous_record_id  TEXT,
    previous_hash       TEXT,
    record_hash         TEXT NOT NULL,
    supersedes          TEXT,
    payload             TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS ix_audit_run ON audit_records (run_id);
CREATE UNIQUE INDEX IF NOT EXISTS ux_audit_single_decision
    ON audit_records (run_id)
    WHERE entry_type = 'decision';
CREATE UNIQUE INDEX IF NOT EXISTS ux_audit_single_supersede
    ON audit_records (supersedes)
    WHERE supersedes IS NOT NULL;

CREATE TRIGGER IF NOT EXISTS audit_no_update
    BEFORE UPDATE ON audit_records
BEGIN
    SELECT RAISE(ABORT, 'audit records are append-only: UPDATE rejected');
END;

CREATE TRIGGER IF NOT EXISTS audit_no_delete
    BEFORE DELETE ON audit_records
BEGIN
    SELECT RAISE(ABORT, 'audit records are append-only: DELETE rejected');
END;
"""

_COLUMNS = (
    "sequence",
    "record_id",
    "run_id",
    "timestamp",
    "entry_type",
    "payload_ref",
    "rules_version",
    "previous_record_id",
    "previous_hash",
    "record_hash",
    "supersedes",
    "payload",
)
_SELECT = f"SELECT {', '.join(_COLUMNS)} FROM audit_records ORDER BY sequence"


class VerificationResult:
    """Outcome of chain verification (FR-005, INV-005).

    ``ok`` is True only when the whole chain is internally consistent and its
    decision/revision semantics hold. ``reason`` names the first failure code and
    ``position`` the offending ``sequence`` when known.
    """

    __slots__ = ("ok", "reason", "detail", "position")

    def __init__(self, ok: bool, reason: str = "ok", detail: str = "", position: int | None = None) -> None:
        self.ok = ok
        self.reason = reason
        self.detail = detail
        self.position = position

    def to_dict(self) -> dict:
        """Return a plain dict view of the verification result (INV-005 / ADR-003)."""
        return {"ok": self.ok, "reason": self.reason, "detail": self.detail, "position": self.position}

    def __repr__(self) -> str:  # pragma: no cover - debug aid
        return f"VerificationResult(ok={self.ok}, reason={self.reason!r}, position={self.position})"


def _row_to_record(row: sqlite3.Row) -> AuditRecord:
    """Build an :class:`AuditRecord` from a stored row, preserving all persisted fields.

    Unlike :func:`make_record` (used on append to *generate* ``payload_ref``),
    materialising a stored row must keep the raw persisted ``payload_ref`` and
    ``record_hash`` verbatim. Recomputing them here would silently "repair" a
    tampered row during read, hiding corruption from verify/replay.
    """
    return AuditRecord(
        record_id=row["record_id"],
        run_id=row["run_id"],
        timestamp=row["timestamp"],
        entry_type=row["entry_type"],
        payload_ref=row["payload_ref"],
        rules_version=row["rules_version"],
        previous_record_id=row["previous_record_id"],
        previous_hash=row["previous_hash"],
        record_hash=row["record_hash"],
        supersedes=row["supersedes"],
        sequence=row["sequence"],
        _payload_json=row["payload"],
    )


class AuditStore:
    """Append-only audit store over one SQLite file with one global chain.

    Public API (ADR-003 §2.6): :meth:`open`, :meth:`append`, :meth:`get`,
    :meth:`iter_run`, :meth:`verified_records`, :meth:`project`,
    :meth:`final_decision`, :meth:`head`, :meth:`verify_chain`. No update/delete
    methods exist; triggers reject such SQL. Anchors: FR-005, INV-005.
    """

    def __init__(self, path: str, *, timeout: float = 30.0) -> None:
        self._path = path
        self._conn = sqlite3.connect(path, timeout=timeout, isolation_level=None)
        self._conn.row_factory = sqlite3.Row
        self._conn.execute("PRAGMA journal_mode=WAL")
        self._conn.executescript(_SCHEMA)

    @classmethod
    def open(cls, path: str, *, timeout: float = 30.0) -> AuditStore:
        """Open (or create) an audit store; idempotent for reopen (FR-005 / INV-005 / ADR-003)."""
        return cls(path, timeout=timeout)

    def close(self) -> None:
        """Close the underlying connection (FR-005 / INV-005 / ADR-003)."""
        self._conn.close()

    def __enter__(self) -> AuditStore:
        return self

    def __exit__(self, exc_type, exc, tb) -> None:
        self.close()

    # -- snapshot + verification -------------------------------------------
    def _snapshot(self) -> list[sqlite3.Row]:
        """Read the whole chain in one SELECT (single consistent snapshot)."""
        return self._conn.execute(_SELECT).fetchall()

    def _verify_rows(self, rows: list[sqlite3.Row]) -> VerificationResult:
        """Verify a full ordered snapshot (FR-005, INV-005, ADR-003 §2.3).

        Checks, walking from the root in ``sequence`` order: strictly increasing
        and continuous sequence, per-row field validity, payload parse and
        ``payload_ref`` match, recomputed ``record_hash``, predecessor link
        continuity, and decision/revision semantics via a per-run
        ``current_terminal`` cursor.
        """
        prev_id: str | None = None
        prev_hash: str | None = None
        expected_seq = 1
        for row in rows:
            seq = row["sequence"]
            if not isinstance(seq, int) or seq != expected_seq:
                return VerificationResult(
                    False, "chain_broken",
                    f"sequence gap: expected {expected_seq} at position {seq}", seq,
                )
            expected_seq += 1

            try:
                payload = json.loads(row["payload"])
            except (ValueError, TypeError) as exc:
                return VerificationResult(
                    False, "malformed_payload", f"cannot parse payload JSON at {row['record_id']!r}: {exc}", seq,
                )

            try:
                validate_append_inputs(
                    record_id=row["record_id"],
                    run_id=row["run_id"],
                    timestamp=row["timestamp"],
                    entry_type=row["entry_type"],
                    payload=payload,
                    rules_version=row["rules_version"],
                    supersedes=row["supersedes"],
                )
            except AuditError as exc:
                return VerificationResult(False, exc.code, f"invalid field at {row['record_id']!r}: {exc.message}", seq)

            try:
                if row["payload_ref"] != payload_ref(payload):
                    return VerificationResult(
                        False, "payload_tampered", f"payload_ref mismatch at {row['record_id']!r}", seq,
                    )
                record = _row_to_record(row)
            except AuditError as exc:
                return VerificationResult(False, exc.code, f"invalid payload at {row['record_id']!r}: {exc.message}", seq)

            if row["previous_record_id"] != prev_id or row["previous_hash"] != prev_hash:
                reason = "orphan_record" if expected_seq == 2 and row["previous_record_id"] is not None else "chain_broken"
                return VerificationResult(
                    False, reason, f"predecessor link mismatch at {row['record_id']!r}", seq,
                )
            if record.recompute_hash() != row["record_hash"]:
                return VerificationResult(
                    False, "chain_broken", f"record_hash mismatch at {row['record_id']!r}", seq,
                )
            prev_id = row["record_id"]
            prev_hash = row["record_hash"]

        return self._verify_semantics(rows)

    @staticmethod
    def _verify_semantics(rows: list[sqlite3.Row]) -> VerificationResult:
        """Decision/revision semantics using a per-run current-terminal cursor.

        Rules (INV-005): at most one initial decision per run; a revision must
        point at the *currently reached* terminal (no future/self/cycle); a run
        cannot revise before its initial decision exists; non-revisions must not
        carry ``supersedes``.
        """
        current_terminal: dict[str, str] = {}
        has_initial: dict[str, bool] = {}
        seen_ids: set[str] = set()
        for row in rows:
            run_id = row["run_id"]
            rid = row["record_id"]
            entry = row["entry_type"]
            supersedes = row["supersedes"]

            if entry == "decision":
                if has_initial.get(run_id):
                    return VerificationResult(
                        False, "invariant_violation", f"run {run_id!r} has multiple initial decisions", row["sequence"],
                    )
                has_initial[run_id] = True
                current_terminal[run_id] = rid
            elif entry == "revision":
                if not has_initial.get(run_id):
                    return VerificationResult(
                        False, "invariant_violation", f"run {run_id!r} revision precedes any initial decision", row["sequence"],
                    )
                if supersedes == rid:
                    return VerificationResult(
                        False, "invariant_violation", f"revision {rid!r} supersedes itself", row["sequence"],
                    )
                if supersedes not in seen_ids:
                    # Future reference or missing record: not yet reached.
                    return VerificationResult(
                        False, "invariant_violation", f"revision {rid!r} supersedes an unreached/unknown record {supersedes!r}", row["sequence"],
                    )
                if current_terminal.get(run_id) != supersedes:
                    return VerificationResult(
                        False, "invariant_violation", f"revision {rid!r} does not supersede the current terminal", row["sequence"],
                    )
                current_terminal[run_id] = rid
            else:
                if supersedes is not None:
                    return VerificationResult(
                        False, "invariant_violation", f"non-revision {rid!r} must not carry supersedes", row["sequence"],
                    )
            seen_ids.add(rid)
        return VerificationResult(True)

    def verify_chain(self) -> VerificationResult:
        """Traverse the entire chain from a single snapshot (FR-005, INV-005)."""
        return self._verify_rows(self._snapshot())

    def _verified_rows(self) -> list[sqlite3.Row]:
        """Return the single snapshot if healthy, else raise ``AuditError``.

        The returned rows are the *same* snapshot that was verified, so callers
        never re-query and risk a split between verification and reads (FR-005).
        """
        rows = self._snapshot()
        result = self._verify_rows(rows)
        if not result.ok:
            # Only invariant_violation keeps its own code; every other failure
            # (malformed payload, sequence gap, tampering...) surfaces as
            # chain_broken, with the precise reason kept in message/context so
            # authoritative reads never look valid on a damaged chain.
            code = "invariant_violation" if result.reason == "invariant_violation" else "chain_broken"
            raise AuditError(
                code,
                f"audit chain is not consistent: {result.reason} ({result.detail})",
                context=result.to_dict(),
            )
        return rows

    @staticmethod
    def _rows_to_records(rows: list[sqlite3.Row], run_id: str | None = None) -> list[AuditRecord]:
        records: list[AuditRecord] = []
        for row in rows:
            if run_id is not None and row["run_id"] != run_id:
                continue
            records.append(_row_to_record(row))
        return records

    def verified_records(self, run_id: str | None = None) -> list[AuditRecord]:
        """Return records from one verified snapshot (FR-005, INV-005).

        Verification and the returned records come from the same SELECT, so the
        event set cannot drift between check and use. Raises ``AuditError`` on a
        broken chain. Used by :func:`replay_run` and authoritative reads.
        """
        return self._rows_to_records(self._verified_rows(), run_id)

    # -- append -------------------------------------------------------------
    def append(
        self,
        *,
        record_id: str,
        run_id: str,
        timestamp: str,
        entry_type: str,
        payload: Any,
        rules_version: str,
        supersedes: str | None = None,
    ) -> AuditRecord:
        """Append one record and return it (FR-005, INV-005).

        ``record_id``/``run_id``/``timestamp``/``payload``/``rules_version`` are
        caller inputs; ``payload_ref``, predecessor links and ``record_hash`` are
        generated here inside the transaction so predecessors cannot be forged.
        The existing chain is verified first; a broken chain refuses the write.
        Any failure rolls back with no partial row.
        """
        validate_append_inputs(
            record_id=record_id,
            run_id=run_id,
            timestamp=timestamp,
            entry_type=entry_type,
            payload=payload,
            rules_version=rules_version,
            supersedes=supersedes,
        )
        # Canonicalise the payload exactly once, then derive an immutable
        # snapshot from that text so later caller mutations cannot affect the
        # computed ref/hash, the inserted row, or the returned record.
        payload_text = canonical_json(payload).decode("utf-8")
        payload_snapshot = json.loads(payload_text)
        pref = payload_ref(payload_snapshot)

        self._conn.execute("BEGIN IMMEDIATE")
        try:
            rows = self._snapshot()
            result = self._verify_rows(rows)
            if not result.ok:
                raise AuditError(
                    "chain_broken",
                    f"refusing append on broken chain: {result.reason} ({result.detail})",
                    context=result.to_dict(),
                )

            if self._conn.execute(
                "SELECT 1 FROM audit_records WHERE record_id = ?", (record_id,)
            ).fetchone() is not None:
                raise AuditError("duplicate_record_id", f"record_id {record_id!r} already exists")

            if entry_type == "decision":
                if self._conn.execute(
                    "SELECT 1 FROM audit_records WHERE run_id = ? AND entry_type = 'decision'", (run_id,)
                ).fetchone() is not None:
                    raise AuditError(
                        "duplicate_decision",
                        f"run {run_id!r} already has an initial decision; use a revision",
                    )
            elif entry_type == "revision":
                self._check_revision_target(run_id=run_id, supersedes=supersedes)

            prev_id = rows[-1]["record_id"] if rows else None
            prev_hash = rows[-1]["record_hash"] if rows else None

            fields = {
                "record_id": record_id,
                "run_id": run_id,
                "timestamp": timestamp,
                "entry_type": entry_type,
                "payload_ref": pref,
                "rules_version": rules_version,
                "previous_record_id": prev_id,
                "previous_hash": prev_hash,
                "supersedes": supersedes,
                "payload": payload_snapshot,
            }
            record_hash = compute_record_hash(fields)
            cursor = self._conn.execute(
                f"INSERT INTO audit_records ({', '.join(_COLUMNS[1:])}) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
                (
                    record_id, run_id, timestamp, entry_type, pref, rules_version,
                    prev_id, prev_hash, record_hash, supersedes, payload_text,
                ),
            )
            sequence = int(cursor.lastrowid)
            self._conn.execute("COMMIT")
        except Exception:
            self._conn.execute("ROLLBACK")
            raise

        return make_record(
            record_id=record_id,
            run_id=run_id,
            timestamp=timestamp,
            entry_type=entry_type,
            payload=payload_snapshot,
            rules_version=rules_version,
            previous_record_id=prev_id,
            previous_hash=prev_hash,
            record_hash=record_hash,
            supersedes=supersedes,
            sequence=sequence,
        )

    def _check_revision_target(self, *, run_id: str, supersedes: str) -> None:
        target = self._conn.execute(
            "SELECT record_id, run_id, entry_type FROM audit_records WHERE record_id = ?", (supersedes,)
        ).fetchone()
        if target is None:
            raise AuditError("invalid_supersede", f"supersedes target {supersedes!r} does not exist")
        if target["run_id"] != run_id:
            raise AuditError("invalid_supersede", "revision must supersede a record in the same run")
        if target["entry_type"] not in ("decision", "revision"):
            raise AuditError("invalid_supersede", "revision must supersede a decision, not an event")
        if self._conn.execute(
            "SELECT 1 FROM audit_records WHERE supersedes = ?", (supersedes,)
        ).fetchone() is not None:
            raise AuditError(
                "invalid_supersede",
                f"{supersedes!r} is not the current terminal decision (already superseded)",
            )

    # -- read API -----------------------------------------------------------
    def get(self, record_id: str) -> AuditRecord | None:
        """Return the record with ``record_id`` or None (FR-005 / INV-005 / ADR-003)."""
        row = self._conn.execute(
            f"SELECT {', '.join(_COLUMNS)} FROM audit_records WHERE record_id = ?", (record_id,)
        ).fetchone()
        return _row_to_record(row) if row is not None else None

    def iter_run(self, run_id: str) -> list[AuditRecord]:
        """Return records for ``run_id`` in global sequence order (FR-005, NFR-004, INV-005 / ADR-003)."""
        rows = self._conn.execute(
            f"SELECT {', '.join(_COLUMNS)} FROM audit_records WHERE run_id = ? ORDER BY sequence", (run_id,)
        ).fetchall()
        return [_row_to_record(row) for row in rows]

    def project(self, run_id: str) -> dict:
        """Return a projection with derived ``superseded_by`` (FR-005, INV-005).

        Built from one verified snapshot; a broken chain raises
        ``AuditError(code=chain_broken)``. ``superseded_by`` is derived from
        successor revisions, never written back.
        """
        records = self.verified_records(run_id)
        superseded_by: dict[str, str] = {}
        for record in records:
            if record.entry_type == "revision" and record.supersedes is not None:
                superseded_by[record.supersedes] = record.record_id
        projected = []
        for record in records:
            item = record.to_dict()
            item["superseded_by"] = superseded_by.get(record.record_id)
            projected.append(item)
        return {
            "run_id": run_id,
            "records": projected,
            "final_decision_id": self._terminal_id(records),
        }

    @staticmethod
    def _terminal_id(records: list[AuditRecord]) -> str | None:
        decisions = [r for r in records if r.entry_type in ("decision", "revision")]
        if not decisions:
            return None
        superseded = {r.supersedes for r in decisions if r.supersedes is not None}
        leaves = [r.record_id for r in decisions if r.record_id not in superseded]
        if len(leaves) != 1:
            raise AuditError(
                "invariant_violation",
                f"run has {len(leaves)} terminal decision leaves, expected exactly 1",
            )
        return leaves[0]

    def final_decision(self, run_id: str) -> AuditRecord:
        """Return the unique terminal decision for ``run_id`` (FR-005, INV-005).

        Uses one verified snapshot; returns the single leaf, else raises.
        """
        records = self.verified_records(run_id)
        terminal_id = self._terminal_id(records)
        if terminal_id is None:
            raise AuditError("invariant_violation", f"run {run_id!r} has no decision")
        for record in records:
            if record.record_id == terminal_id:
                return record
        raise AuditError("invariant_violation", "terminal decision not found")  # pragma: no cover

    def head(self) -> dict:
        """Return ``{record_id, record_hash, count}`` from one snapshot (FR-005 / INV-005 / ADR-003).

        The last row and the count come from the same read, so concurrent appends
        cannot make them inconsistent.
        """
        rows = self._snapshot()
        if not rows:
            return {"record_id": None, "record_hash": None, "count": 0}
        last = rows[-1]
        return {"record_id": last["record_id"], "record_hash": last["record_hash"], "count": len(rows)}


__all__ = ["AuditStore", "VerificationResult"]

